database = []

class LevelData:
    def __init__(self,level,sup,req,passwords,supers):
        if type(lev) is not str or type(sup) is not str or type(req) is not int or type(passwords) is not list or type(supers) is not list:
            raise(TypeError(f"invalid data for level {level}"))
        else:
            self.lev = level
            self.sup = sup
            self.req = req
            self.passwords = passwords
            self.supers = supers
            database.append(self)

#requirements:
# 0 is no requirement
# 1 is water OR bounce
# 2 is bounce
# 3 is two player OR lightning
# 4 is water OR lightning
# 5 is fire AND bounce
# 6 is fire
# 7 is lightning OR bounce
# 8 is bounce AND (fire OR two player)

